-- Migration 0061_import_batch: generated by drizzle-kit (tables, keys, indexes), RLS and purge function hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #546)
-- Bootstrap import (#57 part 1): import_batch, import_batch_file and import_plan. Tenant tables under
-- FORCE RLS with ws_isolation. `unmatched_rows_count` is a counter; no column stores non-matched row
-- content. The plan is purged 30 days after apply by app_purge_import_plans(cutoff), owner-defined
-- because the sweep has no workspace (as app_purge_job_effects, 0006): owner_definer_read on
-- import_batch and import_plan, owner_definer_purge (DELETE) on import_plan. Batch and file rows stay.
-- Expand only: new tables, policies and a function.
CREATE TABLE "import_batch" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"created_by" uuid,
	"status" text DEFAULT 'pending' NOT NULL,
	"file_count" integer DEFAULT 0 NOT NULL,
	"matched_rows" integer DEFAULT 0 NOT NULL,
	"unmatched_rows_count" integer DEFAULT 0 NOT NULL,
	"plan_hash" text,
	"applied_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "import_batch_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "import_batch_status_chk" CHECK (status in ('pending', 'processing', 'ready', 'applied', 'undone', 'failed')),
	CONSTRAINT "import_batch_counts_chk" CHECK (file_count >= 0 and matched_rows >= 0 and unmatched_rows_count >= 0),
	CONSTRAINT "import_batch_plan_hash_chk" CHECK (plan_hash is null or plan_hash ~ '^[0-9a-f]{64}$')
);
--> statement-breakpoint
CREATE TABLE "import_batch_file" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
