	"adapter_id" text,
	"rows_matched" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "import_batch_file_batch_capture_uq" UNIQUE("batch_id","capture_id"),
	CONSTRAINT "import_batch_file_status_chk" CHECK (status in ('pending', 'processing', 'parsed', 'unmatched', 'failed')),
	CONSTRAINT "import_batch_file_rows_chk" CHECK (rows_matched >= 0)
);
