CREATE FUNCTION app_purge_import_plans(cutoff timestamptz) RETURNS bigint
  LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    WITH gone AS (
      DELETE FROM import_plan p
      USING import_batch b
      WHERE b.workspace_id = p.workspace_id AND b.id = p.batch_id
        AND b.applied_at IS NOT NULL AND b.applied_at < cutoff
      RETURNING 1
    )
    SELECT count(*) FROM gone
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_purge_import_plans(timestamptz) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_purge_import_plans(timestamptz) TO causedeck_app;
